-- ★ 历史增量脚本：仅用于升级「早于本功能的老库」。
--   新库一律由 configs/postgres/init.sql 一次建全，init.sql 已包含本文件的全部表。
--   因此日常改 schema 请改 init.sql（或对已有库写新的 migrate_*.sql），不要改本文件，
--   否则会出现两份定义不一致、改了一份不生效的情况。
--   挂载入口：docker-compose.yml 的 postgres 服务把 init.sql 挂到 /docker-entrypoint-initdb.d/。

-- =====================================================================
-- rag_service 元数据表迁移脚本（针对已有数据库增量执行）
-- 对应模块：rag_service/internal/meta/pgstore.go
--
-- 与 init.sql §8 的差异说明（此脚本即把存量库拉齐到该形态）：
--   1. kb_id / doc_id 改为 GENERATED BY DEFAULT AS IDENTITY：
--      服务端经 nextval 预取 ID 后显式插入（CreateKB 前需用 kb_id
--      预建 Milvus Collection），GENERATED ALWAYS 会拒绝显式值
--   2. knowledge_bases 补 tenant 列（proto KnowledgeBase.Tenant，
--      租户过滤 ListKB / KeywordSearch 依赖）
--   3. documents 补 raw_bytes BYTEA（RetryDocument 全流程重跑需原文；
--      MinIO 文件落地后此列可移除，见阶段2计划）
--   4. 新增 agent_kbs 挂载表（BindAgentKB / ListAgentKB 存储）
--   5. chunk_count 类型 INTEGER → BIGINT（proto int64）
--
-- ★ 此脚本 DROP 重建 RAG 四表 —— 仅当表为空或可丢弃时执行！
--   当前状态：表从未投入使用（内存实现阶段），无生产数据。
-- =====================================================================

-- ---- 重建（顺序：先删依赖方）----
DROP TABLE IF EXISTS agent_kbs;
DROP TABLE IF EXISTS chunks;
DROP TABLE IF EXISTS documents;
DROP TABLE IF EXISTS knowledge_bases;

-- ================================================================
-- §8.2 knowledge_bases — 知识库表
-- ================================================================
CREATE TABLE knowledge_bases (
  kb_id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  uid              BIGINT       NOT NULL,
  tenant           VARCHAR(64)  NOT NULL DEFAULT '',
  name             VARCHAR(128) NOT NULL,
  description      VARCHAR(512) NOT NULL DEFAULT '',
  embedding_model  VARCHAR(64)  NOT NULL DEFAULT 'qwen-text-embedding-v3',
  embedding_dim    INTEGER      NOT NULL DEFAULT 1024,
  chunk_size       INTEGER      NOT NULL DEFAULT 512,
  chunk_overlap    INTEGER      NOT NULL DEFAULT 64,
  splitter         VARCHAR(32)  NOT NULL DEFAULT 'recursive',
  doc_count        INTEGER      NOT NULL DEFAULT 0,
  chunk_count      BIGINT       NOT NULL DEFAULT 0,
  status           SMALLINT     NOT NULL DEFAULT 1,
  created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
  deleted_at       TIMESTAMPTZ
);

CREATE INDEX idx_kb_uid    ON knowledge_bases (uid);
CREATE INDEX idx_kb_tenant ON knowledge_bases (tenant);
CREATE TRIGGER trg_knowledge_bases_updated_at
  BEFORE UPDATE ON knowledge_bases FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ================================================================
-- §8.3 documents — 知识库文档表
-- ================================================================
CREATE TABLE documents (
  doc_id      BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kb_id       BIGINT        NOT NULL,
  uid         BIGINT        NOT NULL,
  title       VARCHAR(512)  NOT NULL DEFAULT '',
  file_name   VARCHAR(512)  NOT NULL DEFAULT '',
  file_type   VARCHAR(32)   NOT NULL DEFAULT 'txt',
  file_size   BIGINT        NOT NULL DEFAULT 0,
  file_hash   CHAR(64)      NOT NULL DEFAULT '',
  file_path   VARCHAR(1024) NOT NULL DEFAULT '',
  status      SMALLINT      NOT NULL DEFAULT 0,
  chunk_count INTEGER       NOT NULL DEFAULT 0,
  error_msg   TEXT,
  raw_bytes   BYTEA,
  source_url  VARCHAR(1024) NOT NULL DEFAULT '',
  metadata    JSONB,
  parsed_at   TIMESTAMPTZ,
  indexed_at  TIMESTAMPTZ,
  created_at  TIMESTAMPTZ   NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ   NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ
);

CREATE INDEX idx_documents_kb        ON documents (kb_id, status);
CREATE INDEX idx_documents_file_hash ON documents (kb_id, file_hash);
CREATE TRIGGER trg_documents_updated_at
  BEFORE UPDATE ON documents FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ================================================================
-- §8.4 chunks — 文档切片表
-- ================================================================
CREATE TABLE chunks (
  chunk_id     VARCHAR(64) PRIMARY KEY,
  doc_id       BIGINT      NOT NULL,
  kb_id        BIGINT      NOT NULL,
  seq          INTEGER     NOT NULL,
  content      TEXT        NOT NULL,
  token_count  INTEGER     NOT NULL DEFAULT 0,
  char_count   INTEGER     NOT NULL DEFAULT 0,
  page_no      INTEGER     NOT NULL DEFAULT 0,
  vec_status   SMALLINT    NOT NULL DEFAULT 0,   -- 0待入库 1已入库 2失败
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_chunks_doc          ON chunks (doc_id, seq);
CREATE INDEX idx_chunks_kb           ON chunks (kb_id);
CREATE INDEX idx_chunks_vec_status   ON chunks (vec_status) WHERE vec_status <> 1;
CREATE INDEX idx_chunks_content_trgm ON chunks USING GIN (content gin_trgm_ops);
CREATE TRIGGER trg_chunks_updated_at
  BEFORE UPDATE ON chunks FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ================================================================
-- §8.5 agent_kbs — Agent 知识库挂载表
-- 全量覆盖语义（BindAgentKB 先删后插），无排序列，按 kb_id 稳定输出
-- ================================================================
CREATE TABLE agent_kbs (
  agent_id   BIGINT      NOT NULL,
  kb_id      BIGINT      NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pk_agent_kbs PRIMARY KEY (agent_id, kb_id)
);

CREATE INDEX idx_agent_kbs_kb ON agent_kbs (kb_id);

-- ================================================================
-- 序列起点对齐内存版（首个 nextval 返回 2001 / 3001，
-- 内存实现 nextKB 初始 2000、先自增再返回，首个 ID 即 2001）
-- ================================================================
SELECT setval('knowledge_bases_kb_id_seq', 2000, true);
SELECT setval('documents_doc_id_seq', 3000, true);
